func (q *Queries) ListSoldItems(ctx context.Context) ([]ListSoldItemsRow, error) {
	rows, err := q.db.QueryContext(ctx, listSoldItems)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListSoldItemsRow
	for rows.Next() {
		var i ListSoldItemsRow
		if err := rows.Scan(
			&i.SaleID,
			&i.CashierID,
			&i.TransactionTime,
			&i.ItemID,
			&i.AddedAt,
			&i.Description,
			&i.PriceInCents,
			&i.ItemCategoryID,
			&i.SellerID,
			&i.Donation,
			&i.Charity,
			&i.Large,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

